51	export const buildTree = (data: GlossaryTerm[]): GlossaryTerm[] => {
52	  const nodes: Record<string, GlossaryTerm> = {};
53	
54	  // Create nodes first
55	  data.forEach((obj) => {
56	    nodes[obj.fullyQualifiedName ?? ''] = {
57	      ...obj,
58	      children: obj.children?.length ? [] : undefined,
59	    };
60	  });
61	
62	  // Build the tree structure
63	  const tree: GlossaryTerm[] = [];
64	  data.forEach((obj) => {
65	    const current = nodes[obj.fullyQualifiedName ?? ''];
66	    const parent = nodes[obj.parent?.fullyQualifiedName ?? ''];
67	
68	    if (parent?.children) {
69	      // converting glossaryTerm to EntityReference
70	      parent.children.push({ ...current, type: 'glossaryTerm' });
71	    } else {
72	      tree.push(current);
73	    }
74	  });
75	
76	  return tree;
77	};
