175	export const updateGlossaryTermByFqn = (
176	  glossaryTerms: ModifiedGlossary[],
177	  fqn: string,
178	  newValue: ModifiedGlossary
179	): ModifiedGlossary[] => {
180	  return glossaryTerms.map((term) => {
181	    if (term.fullyQualifiedName === fqn) {
182	      return newValue;
183	    }
184	    if (term.children) {
185	      return {
186	        ...term,
187	        children: updateGlossaryTermByFqn(
188	          term.children as ModifiedGlossary[],
189	          fqn,
190	          newValue
191	        ),
192	      };
193	    }
194	
195	    return term;
196	  }) as ModifiedGlossary[];
