199	// This function finds and gives you the glossary term you're looking for.
200	// You can then use this term or update its information in the Glossary or Term with it's reference created
201	// Reference will only be created if withReference is true
202	export const findItemByFqn = (
203	  list: ModifiedGlossaryTerm[] | Domain[],
204	  fullyQualifiedName: string,
205	  withReference = true
206	): GlossaryTerm | Glossary | ModifiedGlossary | Domain | null => {
207	  for (const item of list) {
208	    if (
209	      (item.fullyQualifiedName ?? (item as ModifiedGlossaryTerm).value) ===
210	      fullyQualifiedName
211	    ) {
212	      return withReference
213	        ? item
214	        : {
215	            ...item,
216	            fullyQualifiedName:
217	              item.fullyQualifiedName ??
218	              (item as ModifiedGlossaryTerm).data?.tagFQN,
219	            ...((item as ModifiedGlossaryTerm).data ?? {}),
220	          };
